# Rubrica delle competenze trasversali: originale, griglia e rubrica riscritta.

ORIG = [('Comunicazione efficace', 'Comunica in modo efficace ed adeguato al contesto. Disponibile al dialogo, rispettoso delle idee altrui.', 'Sviluppa con gli adulti e con i pari una comunicazione chiara ed efficace.', 'Comunica con modalità non sempre adeguate al contesto ma capaci di veicolare il messaggio.', 'Comunica in modo frammentario, da adeguare al contesto.'), ('Partecipazione', 'Partecipa alle attività proposte apportando un contributo personale e finalizzato.', 'Partecipa alle attività proposte assumendo il ruolo e il compito assegnati.', 'Deve essere sollecitato a partecipare alle attività proposte anche con un proprio contributo.', 'Tende a evitare il coinvolgimento diretto nelle attività proposte.'), ('Lavoro di squadra', 'Lavora in gruppo con gli altri assumendo obiettivi da raggiungere e prestando aiuto.', 'Nel gruppo svolge un ruolo attivo contribuendo allo sviluppo del compito.', 'Nel lavoro di squadra accetta di collaborare con gli altri.', 'Predilige il lavoro individuale evitando il confronto nel gruppo.'), ('Cittadinanza / Legalità', 'Ha un comportamento conforme al rispetto delle regole e delle persone improntato alla convivenza solidale.', 'Riconosce importanza alle regole della convivenza e vi si adegua.', 'Deve ancora essere richiamato a dare importanza al rispetto delle regole di convivenza.', 'Deve maturare un approccio più responsabile al rispetto delle regole di convivenza.'), ('Impegno scolastico', 'Evidenzia un costante adempimento dei doveri scolastici supportati da approfondimenti ed iniziative personali anche extrascolastiche.', 'Dimostra consapevolezza dei propri doveri che esegue rispondendo alle consegne date.', 'Evidenzia un impegno discontinuo che non sempre lo conduce ai risultati richiesti. Si richiede maggior impegno in…', 'Va sollecitato a portare a termine impegni e compiti assegnati. Si evidenziano fragilità nelle seguenti discipline:…'), ('Creatività', 'Affronta in modo costruttivo i diversi problemi valutando alternative diverse e assumendo la responsabilità del decidere.', 'Cerca percorsi diversi e originali per arrivare alla soluzione di un problema.', 'È disponibile a ricercare soluzioni nuove a problemi usuali.', 'Predilige eseguire il lavoro seguendo precise indicazioni o percorsi già sperimentati.'), ('Gestione delle emozioni', 'Riconosce le proprie emozioni e le sa gestire in modo appropriato in relazione al benessere proprio e altrui.', 'È in grado di esercitare un buon controllo emotivo su se stesso.', 'Sta imparando a gestire e a tenere sotto controllo le proprie emozioni.', 'Deve ancora maturare un atteggiamento di controllo consapevole sulle proprie emozioni.')]

GRIGLIA = [['Chiara e adeguata al contesto', 'Chiara e ordinata', 'Essenziale, non sempre adeguata', 'Frammentaria, con guida'], ['Propositiva, coinvolge altri', 'Costante, nel ruolo assegnato', 'Su sollecitazione', 'Solo se guidata individualmente'], ['Trainante, sostiene i compagni', 'Attiva nel proprio ruolo', 'Collabora se il compito è chiaro', 'Prevalentemente individuale'], ['Autonomo e responsabile', 'Regolare', 'Con richiami occasionali', 'Con richiami frequenti'], ['Costante, con approfondimenti', 'Regolare, nei tempi', 'Discontinuo', 'Con supporto costante'], ['Confronta alternative e sceglie', 'Propone soluzioni nuove', 'Prova alternative su richiesta', 'Segue procedure note'], ['Consapevole anche nel nuovo', 'Autonoma nel quotidiano', "Con supporto dell'adulto", "Guidata dall'adulto"]]

EVID = ['Discussioni in classe, esposizioni orali, scambi nei lavori di gruppo.', 'Lezioni dialogate, attività laboratoriali, progetti e uscite.', 'Lavori di gruppo, cooperative learning, compiti di realtà.', 'Vita di classe, intervallo, mensa, uscite; uso di spazi e materiali comuni.', 'Compiti a casa, consegne, materiale, rispetto delle scadenze.', 'Compiti di realtà, problemi aperti, attività STEM e laboratoriali.', 'Conflitti, verifiche, imprevisti, feedback ricevuti.']

RUBRICA = [["Adatta registro e contenuto all'interlocutore e alla situazione (adulti, pari, gruppo). Ascolta, riformula il pensiero altrui ed esprime il proprio dissenso con rispetto, motivandolo.", 'Si esprime in modo chiaro e ordinato con adulti e compagni. Ascolta gli interventi altrui e risponde in modo pertinente.', 'Trasmette il messaggio essenziale; il registro non è sempre adatto alla situazione e talvolta interrompe o non tiene conto di quanto detto dagli altri.', "Comunica in modo essenziale; con domande guida dell'adulto riesce a trasmettere il messaggio principale."], ["Interviene di propria iniziativa con proposte pertinenti che fanno avanzare l'attività e coinvolge i compagni.", 'Partecipa con continuità, assumendo il ruolo e il compito assegnati.', 'Partecipa se sollecitato; i suoi interventi sono pertinenti ma occasionali.', "Partecipa all'attività quando è guidato individualmente dall'adulto con richieste precise."], ['Aiuta il gruppo a definire obiettivi e ruoli, sostiene i compagni in difficoltà e media nei disaccordi.', 'Svolge attivamente il proprio ruolo, rispetta tempi e accordi del gruppo e contribuisce al prodotto comune.', 'Collabora quando il compito è assegnato con chiarezza; dentro il gruppo tende a lavorare per conto proprio.', "Nel gruppo svolge una parte del compito quando l'adulto o un compagno gliela indica."], ['Rispetta le regole e le persone anche senza controllo; sa spiegare il senso delle regole e contribuisce a farle rispettare nel gruppo.', 'Rispetta le regole della classe e della scuola e le persone; riconosce i propri errori quando gli vengono segnalati.', 'Rispetta le regole nella maggior parte delle situazioni; talvolta serve un richiamo, al quale risponde correggendo il comportamento.', "Rispetta le regole dopo ripetuti richiami; guidato dall'adulto, riflette sulle conseguenze del proprio comportamento."], ['Porta a termine compiti e consegne con cura e nei tempi; approfondisce di propria iniziativa gli argomenti di studio (domande, ricerche, materiali).', 'Esegue con regolarità compiti e consegne nei tempi stabiliti e porta il materiale richiesto.', 'Svolge compiti e consegne in modo discontinuo: talvolta non rispetta le scadenze o li completa solo in parte.', "Porta a termine compiti e consegne con il supporto dell'adulto (promemoria, suddivisione in passi)."], ['Di fronte a un problema individua più soluzioni, le confronta, sceglie motivando e si assume la responsabilità della scelta.', 'Propone in autonomia soluzioni o percorsi diversi da quelli già sperimentati.', 'Su richiesta, prova una soluzione diversa per problemi già noti.', 'Risolve i problemi seguendo procedure note e indicazioni passo passo.'], ["Riconosce e nomina le proprie emozioni anche in situazioni nuove o di tensione, le gestisce con strategie efficaci e tiene conto dell'effetto delle proprie reazioni sugli altri.", "Nelle situazioni abituali riconosce le proprie emozioni e le gestisce senza l'intervento dell'adulto.", "Riconosce le proprie emozioni; con il supporto dell'adulto usa strategie per gestirle.", "Con l'aiuto dell'adulto dà un nome a ciò che prova e riesce a calmarsi."]]

IO = [["Adatto il modo di parlare a chi ho davanti. Ascolto, ripeto con parole mie le idee degli altri e, se non sono d'accordo, lo dico con rispetto spiegando perché.", 'Mi esprimo in modo chiaro e ordinato con adulti e compagni. Ascolto e rispondo a tono.', 'Riesco a far capire il messaggio principale, ma a volte uso un modo di parlare non adatto o interrompo.', "Riesco a far capire ciò che voglio dire quando l'insegnante mi aiuta con delle domande."], ['Intervengo di mia iniziativa con proposte utili e coinvolgo anche i compagni.', 'Partecipo con costanza e svolgo il ruolo e il compito che mi vengono dati.', 'Partecipo quando qualcuno me lo chiede; intervengo a proposito, ma raramente.', "Partecipo quando l'insegnante mi dà indicazioni precise solo per me."], ['Aiuto il gruppo a decidere obiettivi e ruoli, sostengo chi è in difficoltà e aiuto a risolvere i disaccordi.', 'Faccio la mia parte nel gruppo, rispetto tempi e accordi e contribuisco al lavoro comune.', 'Collaboro quando il mio compito è chiaro, ma spesso lavoro per conto mio.', 'Nel gruppo svolgo una parte del lavoro quando qualcuno me la indica.'], ['Rispetto le regole anche quando nessuno controlla, so spiegare a cosa servono e aiuto il gruppo a rispettarle.', 'Rispetto le regole della classe e della scuola e le persone; se sbaglio e me lo fanno notare, lo riconosco.', 'Di solito rispetto le regole; a volte serve un richiamo, e allora correggo il mio comportamento.', "Rispetto le regole dopo diversi richiami; con l'insegnante ragiono sulle conseguenze di ciò che faccio."], ['Porto a termine i compiti con cura e nei tempi e approfondisco per conto mio gli argomenti che studiamo.', 'Svolgo compiti e consegne con regolarità e nei tempi; porto il materiale.', 'Svolgo i compiti in modo discontinuo: a volte salto una scadenza o li faccio solo in parte.', 'Porto a termine compiti e consegne quando qualcuno mi aiuta a organizzarmi.'], ['Davanti a un problema trovo più soluzioni, le confronto, scelgo spiegando perché e mi prendo la responsabilità della scelta.', 'Propongo da solo soluzioni o strade diverse da quelle già viste.', 'Se me lo chiedono, provo una soluzione diversa per un problema che conosco.', 'Risolvo i problemi seguendo procedure che conosco e indicazioni passo passo.'], ['Riconosco e so dare un nome alle mie emozioni anche in situazioni nuove o di tensione; le gestisco e penso a come le mie reazioni fanno sentire gli altri.', 'Nelle situazioni di tutti i giorni riconosco le mie emozioni e le gestisco da solo.', "Riconosco le mie emozioni; per gestirle uso delle strategie con l'aiuto di un adulto.", "Con l'aiuto di un adulto riesco a dare un nome a ciò che provo e a calmarmi."]]

